// Writes src/client.gen.ts from the contract: one typed method per endpoint.
//   pnpm --filter @luvallplay/api generate
// apps/web/tests/api-contract.test.ts fails when the file is out of date.
import { writeFileSync } from "node:fs";
import { API_PREFIX, API_VERSION, ENDPOINTS } from "../src/contract.ts";

export function generateClient(): string {
  const lines: string[] = [
    "// GENERATED by packages/api/scripts/generate.ts from src/contract.ts. Don't edit by hand:",
    "// change the contract and run `pnpm --filter @luvallplay/api generate`.",
    'import type { BodyOf, ParamsOf, QueryOf, ResponseOf } from "./contract.ts";',
    'import type { Transport } from "./client.ts";',
    "",
    "type Options = { signal?: AbortSignal };",
    "",
    "export function createApi(transport: Transport) {",
    "  return {",
  ];
  const groups = new Map<string, string[]>();
  for (const id of Object.keys(ENDPOINTS).sort()) {
    const e = ENDPOINTS[id as keyof typeof ENDPOINTS] as { method: string; path: string; params?: unknown; query?: unknown; body?: unknown; auth: string };
    const [group, name] = id.split(".");
    const args: string[] = [];
    const pass: string[] = [];
    if (e.params) { args.push(`params: ParamsOf<"${id}">`); pass.push("params"); }
    if (e.query) { args.push(`query: QueryOf<"${id}">`); pass.push("query"); }
    if (e.body) { args.push(`body: BodyOf<"${id}">`); pass.push("body"); }
    args.push("options?: Options");
    const method = [
      `      /** ${e.method} ${e.path} (${e.auth === "public" ? "no sign-in needed" : "signed in"}) */`,
      `      ${name}: (${args.join(", ")}) =>`,
      `        transport.call("${id}", { ${[...pass, "signal: options?.signal"].join(", ")} }) as Promise<ResponseOf<"${id}">>,`,
    ];
    groups.set(group, [...(groups.get(group) ?? []), ...method]);
  }
  for (const [group, body] of groups) lines.push(`    ${group}: {`, ...body, "    },");
  lines.push("  };", "}", "", "export type Api = ReturnType<typeof createApi>;", "");
  return lines.join("\n");
}

/**
 * The part of the contract the client needs at run time (method, path, who
 * may call), without the zod schemas, so the app's bundle doesn't carry zod.
 */
export function generateRoutes(): string {
  const lines = [
    "// GENERATED by packages/api/scripts/generate.ts from src/contract.ts. Don't edit by hand:",
    "// change the contract and run `pnpm --filter @luvallplay/api generate`.",
    `export const API_VERSION = "${API_VERSION}";`,
    `export const API_PREFIX = "${API_PREFIX}";`,
    "",
    "export const ROUTES = {",
  ];
  for (const id of Object.keys(ENDPOINTS).sort()) {
    const e = ENDPOINTS[id as keyof typeof ENDPOINTS] as { method: string; path: string; auth: string };
    lines.push(`  "${id}": { method: "${e.method}", path: "${e.path}", auth: "${e.auth}" },`);
  }
  lines.push("} as const;", "", "export type RouteId = keyof typeof ROUTES;", "");
  return lines.join("\n");
}

if (import.meta.url === `file://${process.argv[1]}`) {
  writeFileSync(new URL("../src/client.gen.ts", import.meta.url), generateClient());
  writeFileSync(new URL("../src/routes.gen.ts", import.meta.url), generateRoutes());
  console.log("wrote src/client.gen.ts and src/routes.gen.ts");
}
